	/**
	 * Update one or several filters applied on a Liveboard.
	 * Payload: {@link UpdateFiltersRequest}.
	 * @param - Includes the following keys:
	 * - `filter`: A single filter object containing column name, filter operator, and
	 * values.
	 * - `filters`: Multiple filter objects with column name, filter operator,
	 * and values for each.
	 *
	 * Each filter object must include the following attributes:
	 *
	 * `column` - Name of the column to filter on.
	 *
	 * `oper`  - Filter operator, for example, EQ, IN, CONTAINS.
	 *  For information about the supported filter operators,
	 *  see link:https://developers.thoughtspot.com/docs/runtime-filters#rtOperator[Developer Documentation].
	 *
	 * `values` - An array of one or several values. The value definition on the
	 *  data type you choose to filter on. For a complete list of supported data types,
	 *  see
	 *  link:https://developers.thoughtspot.com/docs/runtime-filters#_supported_data_types[Supported
	 *  data types].
	 *
	 * `type`  - To update filters for date time, specify the date format type.
	 * For more information and examples, see link:https://developers.thoughtspot.com/docs/embed-liveboard#_date_filters[Date filters].
	 *
	 * `applicability` - Optional. Scopes the filter to a specific target,
	 * for example, a single Liveboard tab. Available from SDK: 1.53.0 |
	 * ThoughtSpot: 26.10.0.cl. Includes the following attributes:
	 *
	 *  - `level`: The scope of the filter: `LIVEBOARD`, `TAB`, or `GROUP`.
	 *  - `targetId`: The GUID of the target, for example, the tab GUID.
	 *    Required when `level` is `TAB` or `GROUP`. Do not pass it when
	 *    `level` is `LIVEBOARD`, since the filter applies to the whole
	 *    Liveboard.
	 * @example
	 * ```js
	 *
	 * liveboardEmbed.trigger(HostEvent.UpdateFilters, {
	 *     filter: {
	 *         column: "item type",
	 *         oper: "IN",
	 *         values: ["bags","shirts"]
	 *        }
	 *    });
	 * ```
	 * @example
	 * ```js
	 *
	 * liveboardEmbed.trigger(HostEvent.UpdateFilters, {
	 *     filter: {
	 *         column: "date",
	 *         oper: "EQ",
	 *         values: ["JULY","2023"],
	 *         type: "MONTH_YEAR"
	 *        }
	 *    });
	 * ```
	 * @example
	 *
	 * ```js
	 * liveboardEmbed.trigger(HostEvent.UpdateFilters, {
	 *  filters: [{
	 *      column: "Item Type",
	 *      oper: 'IN',
	 *      values: ["bags","shirts"]
	 *  },
	 *    {
	 *      column: "Region",
	 *      oper: 'IN',
	 *      values: ["West","Midwest"]
	 *  },
	 *    {
	 *      column: "Date",
	 *      oper: 'EQ',
	 *      values: ["2023-07-31"],
	 *      type: "EXACT_DATE"
	 *    }]
	 * });
	 * ```
	 * If there are multiple columns with the same name, consider
	 * using `WORKSHEET_NAME::COLUMN_NAME` format.
	 *
	 * @example
	 *
	 * ```js
	 * liveboardEmbed.trigger(HostEvent.UpdateFilters, {
	 *  filters: [{
	 *      column: "(Sample) Retail - Apparel::city",
	 *      oper: 'IN',
	 *      values: ["atlanta"]
	 *  },
	 *  {
	 *      column: "(Sample) Retail - Apparel::Region",
	 *      oper: 'IN',
	 *      values: ["West","Midwest"]
	 *  }]
	 * });
	 * ```
	 * @example
	 * ```js
	 * // Update filters from liveboard context
	 * import { ContextType } from '@thoughtspot/visual-embed-sdk';
	 * liveboardEmbed.trigger(HostEvent.UpdateFilters, {
	 *     filter: {
	 *         column: "item type",
	 *         oper: "IN",
	 *         values: ["shoes", "boots"]
	 *     }
	 * }, ContextType.Liveboard);
	 * ```
	 * @example
	 * ```js
	 * // Scope the filter to a specific Liveboard tab
	 * liveboardEmbed.trigger(HostEvent.UpdateFilters, {
	 *     filter: {
	 *         column: "item type",
	 *         oper: "IN",
	 *         values: ["bags", "shirts"],
	 *         applicability: {
	 *             level: "TAB",
	 *             targetId: "e0836cad-4fdf-42d4-bd97-567a6b2a6058"
	 *         }
	 *     }
	 * });
	 * ```
	 * @version SDK: 1.23.0 | ThoughtSpot: 9.4.0.cl
	 */
	UpdateFilters = "updateFilters",
